<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Keranjang</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h4">Keranjang</h1><a class="btn btn-outline-secondary" href="<?php echo site_url('customer/catalog'); ?>">Lanjut Belanja</a></div>
<?php if (!$items): ?><div class="alert alert-info">Keranjang masih kosong.</div><?php else: ?><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Produk</th><th>Jumlah</th><th>Harga</th><th>Subtotal</th><th></th></tr></thead><tbody><?php $total=0; foreach ($items as $item): $subtotal=(float)$item->selling_price*(float)$item->quantity;$total+=(float)$subtotal; ?><tr><td><?php echo html_escape($item->name); ?></td><td><?php echo number_format((float)$item->quantity,3,',','.'); ?></td><td>Rp <?php echo number_format((float)$item->selling_price,0,',','.'); ?></td><td>Rp <?php echo number_format($subtotal,0,',','.'); ?></td><td><form method="post" action="<?php echo site_url('customer/cart/remove_item/'.$item->id); ?>"><input type="hidden" name="<?php echo $this->security->get_csrf_token_name(); ?>" value="<?php echo $this->security->get_csrf_hash(); ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div><div class="card-footer d-flex justify-content-between"><strong>Total: Rp <?php echo number_format($total,0,',','.'); ?></strong><a class="btn btn-success" href="<?php echo site_url('customer/checkout'); ?>">Checkout</a></div></div><?php endif; ?></main></body></html>
